import type { Dayjs } from 'dayjs'

export type OccurrenceException = {
  /** start of the occurrence generated by the series, local time */
  occurrence: string
  cancelled?: boolean
  /** only the fields changed for this occurrence */
  values?: Record<string, unknown>
}

export function occurrenceKey (date: Dayjs): string {
  return date.format('YYYY-MM-DDTHH:mm')
}

export function parseExceptions (raw: unknown): OccurrenceException[] {
  let value = raw
  if (typeof value === 'string') {
    if (!value.trim()) return []
    try {
      value = JSON.parse(value)
    } catch {
      return []
    }
  }
  if (!Array.isArray(value)) return []
  return value
    .filter((entry): entry is OccurrenceException =>
      !!entry && typeof entry === 'object' && typeof (entry as OccurrenceException).occurrence === 'string')
    .sort((a, b) => a.occurrence.localeCompare(b.occurrence))
}

export function findException (entries: OccurrenceException[], occurrence: string): OccurrenceException | undefined {
  return entries.find(entry => entry.occurrence === occurrence)
}

export function mergeException (line: Record<string, unknown>, exception: OccurrenceException | undefined): Record<string, unknown> {
  if (!exception || exception.cancelled || !exception.values) return line
  return { ...line, ...exception.values }
}

/** fields whose value differs from the series occurrence, null included to clear a field */
export function changedValues (
  data: Record<string, unknown>,
  baseline: Record<string, unknown>,
  keys: string[]
): Record<string, unknown> {
  const values: Record<string, unknown> = {}
  for (const key of keys) {
    const next = data[key] ?? null
    const previous = baseline[key] ?? null
    if (JSON.stringify(next) !== JSON.stringify(previous)) values[key] = next
  }
  return values
}

function sortExceptions (entries: OccurrenceException[]): OccurrenceException[] {
  return [...entries].sort((a, b) => a.occurrence.localeCompare(b.occurrence))
}

export function setOccurrenceException (
  entries: OccurrenceException[],
  occurrence: string,
  values: Record<string, unknown>
): OccurrenceException[] {
  const rest = entries.filter(entry => entry.occurrence !== occurrence)
  if (!Object.keys(values).length) return sortExceptions(rest)
  return sortExceptions([...rest, { occurrence, values }])
}

export function cancelOccurrence (entries: OccurrenceException[], occurrence: string): OccurrenceException[] {
  return sortExceptions([
    ...entries.filter(entry => entry.occurrence !== occurrence),
    { occurrence, cancelled: true }
  ])
}

export function removeOccurrenceException (entries: OccurrenceException[], occurrence: string): OccurrenceException[] {
  return sortExceptions(entries.filter(entry => entry.occurrence !== occurrence))
}

/** the value to send to the line API: text columns hold the JSON, structured ones the array */
export function serializeExceptions (entries: OccurrenceException[], fieldType?: string): unknown {
  return fieldType === 'string' ? JSON.stringify(entries) : entries
}
